whenever sqlerror exit failure rollback
set define off
connect -name IMART
prompt -- Deploy the APEXlang dummy-button guard only.
begin
  apex_util.set_security_group_id(4744311978888504);
  wwv_flow_imp.component_begin(p_version_yyyy_mm_dd=>'2026.03.30',p_release=>'26.1.2',p_default_workspace_id=>4744311978888504,p_default_application_id=>105,p_default_id_offset=>7541489808702750,p_default_owner=>'IMART');
  wwv_flow_imp.g_varchar2_table := wwv_flow_imp.empty_varchar2_table;
  wwv_flow_imp.g_varchar2_table(1) := '';
  wwv_flow_imp.g_varchar2_table(2) := '';
  wwv_flow_imp_shared.create_app_static_file(p_id=>wwv_flow_imp.id(7711000000001120),p_file_name=>'hspl-dummy-button-guard.js',p_mime_type=>'application/javascript',p_file_charset=>'utf-8',p_file_content=>wwv_flow_imp.varchar2_to_blob(wwv_flow_imp.g_varchar2_table));
  wwv_flow_imp.component_end;
  commit;
end;
/
declare l_js varchar2(32767); begin
  select javascript_file_urls into l_js from apex_260100.wwv_flows where id=105 for update;
  l_js := regexp_replace(l_js, chr(10)||'#APP_FILES#hspl-dummy-button-guard.js[?]cb=[^[:space:]]+', '');
  update apex_260100.wwv_flows set javascript_file_urls=rtrim(l_js)||chr(10)||'#APP_FILES#hspl-dummy-button-guard.js?cb=20260915d', files_version=files_version+1 where id=105;
  commit; end;
/
exit
